120	/// A 100% safe implementation of a bytecode stream.
121	///
122	/// This is a thin wrapper around an index into a `&[u8]`.
123	#[derive(Clone, Copy, Debug)]
124	pub struct SafeBytecodeStream<'a> {
125	    bytecode: &'a [u8],
126	    position: usize,
127	}
