4	struct Inst<'a> {
5	    snake_name: &'a str,
6	    name: &'a str,
7	    fields: &'a [(&'a str, &'a str)],
8	}
9	
10	macro_rules! define {
11	    (
12	        $(
13	            $( #[$attr:meta] )*
14	            $snake_name:ident = $name:ident $( { $( $field:ident : $field_ty:ty ),* } )? ;
15	        )*
16	    ) => {
17	        &[$(Inst {
18	            snake_name: stringify!($snake_name),
19	            name: stringify!($name),
20	            fields: &[$($( (stringify!($field), stringify!($field_ty)), )*)?],
21	        }),*]
22	        // helpers.push_str(concat!("(define pulley_", stringify!($snake_name), " ("));
23	    };
24	}
25	
26	const OPS: &[Inst<'_>] = pulley_interpreter::for_each_op!(define);
27	const EXTENDED_OPS: &[Inst<'_>] = pulley_interpreter::for_each_extended_op!(define);
28	
29	enum Operand<'a> {
30	    Normal {
31	        name: &'a str,
32	        ty: &'a str,
33	    },
34	    Writable {
35	        name: &'a str,
36	        ty: &'a str,
37	    },
38	    TrapCode {
39	        name: &'a str,
40	        ty: &'a str,
41	    },
42	    Binop {
43	        dst: &'a str,
44	        src1: &'a str,
45	        src2: &'a str,
46	    },
47	}
48	
49	impl Inst<'_> {
50	    fn operands(&self) -> impl Iterator<Item = Operand<'_>> {
51	        self.fields
52	            .iter()
53	            .map(|(name, ty)| match (*name, *ty) {
54	                ("operands", binop) => {
55	                    // Parse "BinaryOperands < A >"` as A/A/A
56	                    // Parse "BinaryOperands < A, B >"` as A/B/A
57	                    // Parse "BinaryOperands < A, B, C >"` as A/B/C
58	                    let mut parts = binop
59	                        .strip_prefix("BinaryOperands <")
60	                        .unwrap()
61	                        .strip_suffix(">")
62	                        .unwrap()
63	                        .trim()
64	                        .split(',')
65	                        .map(|x| x.trim());
66	                    let dst = parts.next().unwrap();
67	                    let src1 = parts.next().unwrap_or(dst);
68	                    let src2 = parts.next().unwrap_or(dst);
69	                    Operand::Binop { dst, src1, src2 }
70	                }
71	                ("dst", ty) => Operand::Writable { name, ty },
72	                (name, ty) => Operand::Normal { name, ty },
73	            })
74	            .chain(if self.name.contains("Trap") {
75	                Some(Operand::TrapCode {
76	                    name: "code",
77	                    ty: "TrapCode",
78	                })
79	            } else {
80	                None
81	            })
82	    }
83	
84	    fn skip(&self) -> bool {
85	        match self.name {
86	            // Skip instructions related to control-flow as those require
87	            // special handling with `MachBuffer`.
88	            "Jump" | "Call" | "CallIndirect" => true,
89	
90	            // Skip special instructions not used in Cranelift.
91	            "XPush32Many" | "XPush64Many" | "XPop32Many" | "XPop64Many" => true,
92	
93	            // Skip more branching-related instructions.
94	            n => n.starts_with("Br"),
95	        }
96	    }
97	}
